package com.aicoo.workspace;

import com.aicoo.common.*;
import com.aicoo.security.*;
import com.aicoo.security.Policy.Actor;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.security.oauth2.jwt.Jwt;
import java.time.*;
import java.util.*;
import static com.aicoo.common.Db.*;

@Service public class WorkspaceService {
    public record NewWorkspace(@NotBlank @Size(max=100)String name){}
    public record Scope(@NotNull UUID workspaceChildId,@NotEmpty List<@NotBlank String> capabilities){}
    public record Invite(@NotBlank @Email String email,@Pattern(regexp="admin|guardian|sitter|staff|viewer") @NotNull String role,
                         @NotEmpty List<@Valid Scope> children,Instant validFrom,@NotNull @Future Instant validUntil){}
    public record Grant(@NotNull UUID membershipId,@NotEmpty List<String> capabilities,Instant validFrom,Instant validUntil){}
    public record Share(@NotNull UUID childId,@NotNull UUID toWorkspaceId,@NotEmpty List<String> scopes,@NotBlank @Size(max=500)String consentRef,@NotNull @Future Instant expiresAt){}
    private final Db db;private final Policy policy;private final Secrets secrets;private final MailDelivery mail;private final Audit audit;private final Idempotency idem;private final boolean allowInstitutions;
    public WorkspaceService(Db db,Policy policy,Secrets secrets,MailDelivery mail,Audit audit,Idempotency idem,@Value("${app.allow-institutions}")boolean allowInstitutions){this.db=db;this.policy=policy;this.secrets=secrets;this.mail=mail;this.audit=audit;this.idem=idem;this.allowInstitutions=allowInstitutions;}
    public Object workspaces(UUID user){return Map.of("items",db.list("SELECT w.id,w.type,w.name,m.id AS \"membershipId\",m.role FROM memberships m JOIN workspaces w ON w.id=m.workspace_id WHERE m.user_id=:u AND m.status='active' AND w.status='active' ORDER BY w.created_at,w.id",p("u",user)));}
    @Transactional public Object create(Jwt jwt,NewWorkspace body){if(!allowInstitutions)throw ApiException.forbidden("INSTITUTION_CREATION_DISABLED");UUID user=UUID.fromString(jwt.getSubject());if(!Boolean.TRUE.equals(db.required("SELECT email_verified FROM users WHERE id=:u",p("u",user),"USER_NOT_FOUND").get("email_verified")))throw ApiException.forbidden("EMAIL_VERIFICATION_REQUIRED");UUID ws=UUID.randomUUID(),member=UUID.randomUUID();db.update("INSERT INTO workspaces(id,type,name,created_by) VALUES(:id,'INSTITUTION',:name,:u)",p("id",ws,"name",body.name(),"u",user));db.update("INSERT INTO memberships(id,workspace_id,user_id,role) VALUES(:id,:ws,:u,'owner')",p("id",member,"ws",ws,"u",user));audit.record(ws,user,"workspace.create","workspace",ws);return p("id",ws,"type","INSTITUTION","name",body.name(),"membershipId",member);}
    public Object members(Actor actor){policy.manager(actor);return Map.of("items",db.list("SELECT id,user_id AS \"userId\",role,status FROM memberships WHERE workspace_id=:ws ORDER BY created_at,id",p("ws",actor.workspaceId())));}
    public Object links(Actor actor){policy.manager(actor);return Map.of("items",db.list("SELECT id,child_id AS \"childId\",link_status AS \"linkStatus\",share_grant_id AS \"shareGrantId\" FROM workspace_children WHERE workspace_id=:ws AND link_status='active' ORDER BY created_at,id",p("ws",actor.workspaceId())));}
    @Transactional public Object invite(Actor actor,Invite body,String key){policy.verified(actor);if(body.role().equals("admin")&&!actor.role().equals("owner"))throw ApiException.forbidden("OWNER_REQUIRED");return idem.execute(actor.membershipId(),key,"invitation.create",body,()->{
        Instant from=body.validFrom()==null?Instant.now():body.validFrom();if(!body.validUntil().isAfter(from))throw ApiException.invalid("INVALID_GRANT_PERIOD");
        if(new HashSet<>(body.children().stream().map(Scope::workspaceChildId).toList()).size()!=body.children().size())throw ApiException.invalid("DUPLICATE_CHILD_SCOPE");
        for(Scope scope:body.children()){var link=db.required("SELECT * FROM workspace_children WHERE id=:id AND workspace_id=:ws AND link_status='active'",p("id",scope.workspaceChildId(),"ws",actor.workspaceId()),"CHILD_NOT_ACCESSIBLE");policy.validateCaps(actor,id(link,"child_id"),body.role(),scope.capabilities());}
        UUID id=UUID.randomUUID();String token=Secrets.random();Instant expiry=Instant.now().plus(Duration.ofHours(48));
        db.update("INSERT INTO invitations(id,workspace_id,invited_email_hash,target_role,token_hash,expires_at,grant_valid_from,grant_valid_until,created_by) VALUES(:id,:ws,:email,:role,:token,:expires,:from,:until,:user)",p("id",id,"ws",actor.workspaceId(),"email",secrets.emailHash(body.email()),"role",body.role(),"token",Secrets.hash(token),"expires",expiry,"from",from,"until",body.validUntil(),"user",actor.userId()));
        for(Scope scope:body.children())db.update("INSERT INTO invitation_child_scopes(invitation_id,workspace_child_id,workspace_id,capabilities) VALUES(:id,:wc,:ws,cast(:caps as jsonb))",p("id",id,"wc",scope.workspaceChildId(),"ws",actor.workspaceId(),"caps",db.json(scope.capabilities())));
        mail.deliver(body.email(),"돌봄 초대",token);audit.record(actor.workspaceId(),actor.userId(),"invitation.create","invitation",id);
        // Tokens are returned only in local mode, never persisted in idempotency responses.
        return p("id",id,"expiresAt",expiry,"delivery","created");
    });}
    @Transactional public Map<String,Object> invitationToken(Actor actor,UUID invitation){
        if(secrets.production)throw ApiException.notFound("NOT_FOUND");
        var row=db.required("SELECT * FROM invitations WHERE id=:id AND workspace_id=:ws AND created_by=:u AND accepted_at IS NULL AND revoked_at IS NULL AND expires_at>now() FOR UPDATE",p("id",invitation,"ws",actor.workspaceId(),"u",actor.userId()),"INVITATION_NOT_ACCESSIBLE");
        String token=Secrets.random();db.update("UPDATE invitations SET token_hash=:hash WHERE id=:id",p("hash",Secrets.hash(token),"id",invitation));return Map.of("invitationToken",token,"delivery","local_only");
    }
    @Transactional public Object accept(Jwt jwt,String token,String key){if(key==null||key.isBlank())throw ApiException.invalid("IDEMPOTENCY_KEY_REQUIRED");UUID user=UUID.fromString(jwt.getSubject());var profile=db.required("SELECT * FROM users WHERE id=:id AND status='active'",p("id",user),"USER_NOT_FOUND");if(!Boolean.TRUE.equals(profile.get("email_verified")))throw ApiException.forbidden("EMAIL_VERIFICATION_REQUIRED");
        var invitation=db.required("SELECT * FROM invitations WHERE token_hash=:hash FOR UPDATE",p("hash",Secrets.hash(token)),"INVITATION_NOT_FOUND");UUID invitationId=id(invitation,"id"),ws=id(invitation,"workspace_id");
        if(invitation.get("revoked_at")!=null)throw ApiException.conflict("INVITE_REVOKED");if(!instant(invitation,"expires_at").isAfter(Instant.now())||!instant(invitation,"grant_valid_until").isAfter(Instant.now()))throw ApiException.conflict("INVITE_EXPIRED");
        if(!Secrets.equal(text(invitation,"invited_email_hash"),secrets.emailHash(text(profile,"email"))))throw ApiException.forbidden("INVITED_EMAIL_MISMATCH");
        if(invitation.get("accepted_at")!=null){if(!user.equals(invitation.get("accepted_by")))throw ApiException.conflict("INVITE_ALREADY_USED");var member=db.required("SELECT id FROM memberships WHERE workspace_id=:ws AND user_id=:u AND status='active'",p("ws",ws,"u",user),"MEMBER_NOT_ACCESSIBLE");return p("workspaceId",ws,"membershipId",member.get("id"),"invitationId",invitationId);}
        var scopes=db.list("SELECT s.*,wc.child_id FROM invitation_child_scopes s JOIN workspace_children wc ON wc.id=s.workspace_child_id WHERE s.invitation_id=:id AND wc.link_status='active'",p("id",invitationId));
        var inviter=db.required("SELECT id FROM memberships WHERE workspace_id=:ws AND user_id=:u AND status='active'",p("ws",ws,"u",invitation.get("created_by")),"INVITER_NOT_ACCESSIBLE");Actor origin=policy.memberActor(id(inviter,"id"));
        if(scopes.isEmpty())throw ApiException.conflict("INVITE_SCOPE_EXPIRED");for(var scope:scopes)policy.validateCaps(origin,id(scope,"child_id"),text(invitation,"target_role"),strings(scope,"capabilities"));
        var existing=db.one("SELECT * FROM memberships WHERE workspace_id=:ws AND user_id=:u FOR UPDATE",p("ws",ws,"u",user));UUID membership=existing.map(m->id(m,"id")).orElseGet(UUID::randomUUID);
        if(existing.isPresent()&&(!"active".equals(existing.get().get("status"))||!existing.get().get("role").equals(invitation.get("target_role"))))throw ApiException.conflict("MEMBERSHIP_ROLE_CONFLICT");
        if(existing.isEmpty())db.update("INSERT INTO memberships(id,workspace_id,user_id,role) VALUES(:id,:ws,:u,:role)",p("id",membership,"ws",ws,"u",user,"role",invitation.get("target_role")));
        return idem.execute(membership,key,"invitation.accept:"+invitationId,Map.of("invitationId",invitationId),()->{
            for(var scope:scopes)db.update("INSERT INTO child_access_grants(id,workspace_child_id,membership_id,workspace_id,capabilities,valid_from,valid_until,invitation_id) VALUES(:id,:wc,:m,:ws,cast(:caps as jsonb),:from,:until,:inv)",p("id",UUID.randomUUID(),"wc",scope.get("workspace_child_id"),"m",membership,"ws",ws,"caps",db.json(scope.get("capabilities")),"from",invitation.get("grant_valid_from"),"until",invitation.get("grant_valid_until"),"inv",invitationId));
            db.update("UPDATE invitations SET accepted_at=now(),accepted_by=:u WHERE id=:id",p("u",user,"id",invitationId));audit.record(ws,user,"invitation.accept","invitation",invitationId);return p("workspaceId",ws,"membershipId",membership,"invitationId",invitationId);
        });
    }
    @Transactional public void revokeInvitation(Actor actor,UUID id){policy.manager(actor);db.required("SELECT id FROM invitations WHERE id=:id AND workspace_id=:ws FOR UPDATE",p("id",id,"ws",actor.workspaceId()),"INVITATION_NOT_ACCESSIBLE");db.update("UPDATE invitations SET revoked_at=COALESCE(revoked_at,now()) WHERE id=:id",p("id",id));db.update("UPDATE child_access_grants SET revoked_at=COALESCE(revoked_at,now()) WHERE invitation_id=:id",p("id",id));db.update("UPDATE stream_access_tokens SET revoked_at=now() WHERE (membership_id,child_id) IN (SELECT g.membership_id,wc.child_id FROM child_access_grants g JOIN workspace_children wc ON wc.id=g.workspace_child_id WHERE g.invitation_id=:id)",p("id",id));audit.record(actor.workspaceId(),actor.userId(),"invitation.revoke","invitation",id);}
    @Transactional public Object grant(Actor actor,UUID linkId,UUID grantId,Grant body){policy.verified(actor);var link=db.required("SELECT * FROM workspace_children WHERE id=:id AND workspace_id=:ws AND link_status='active'",p("id",linkId,"ws",actor.workspaceId()),"CHILD_NOT_ACCESSIBLE");UUID child=id(link,"child_id");var member=db.required("SELECT * FROM memberships WHERE id=:m AND workspace_id=:ws AND status='active'",p("m",body.membershipId(),"ws",actor.workspaceId()),"MEMBER_NOT_ACCESSIBLE");policy.validateCaps(actor,child,text(member,"role"),body.capabilities());Instant from=body.validFrom()==null?Instant.now():body.validFrom();if(body.validUntil()!=null&&!body.validUntil().isAfter(from)||"sitter".equals(member.get("role"))&&body.validUntil()==null)throw ApiException.invalid("INVALID_GRANT_PERIOD");
        UUID id=grantId==null?UUID.randomUUID():grantId;if(grantId==null)db.update("INSERT INTO child_access_grants(id,workspace_child_id,membership_id,workspace_id,capabilities,valid_from,valid_until) VALUES(:id,:wc,:m,:ws,cast(:caps as jsonb),:from,:until)",p("id",id,"wc",linkId,"m",body.membershipId(),"ws",actor.workspaceId(),"caps",db.json(body.capabilities()),"from",from,"until",body.validUntil()));else{int count=db.update("UPDATE child_access_grants SET capabilities=cast(:caps as jsonb),valid_from=:from,valid_until=:until WHERE id=:id AND workspace_id=:ws AND workspace_child_id=:wc AND membership_id=:m AND revoked_at IS NULL",p("caps",db.json(body.capabilities()),"from",from,"until",body.validUntil(),"id",id,"ws",actor.workspaceId(),"wc",linkId,"m",body.membershipId()));if(count==0)throw ApiException.notFound("GRANT_NOT_ACCESSIBLE");policy.revokeStreams(body.membershipId(),child);}audit.record(actor.workspaceId(),actor.userId(),"grant.write","grant",id);return p("id",id,"membershipId",body.membershipId(),"workspaceChildId",linkId,"capabilities",body.capabilities(),"validFrom",from,"validUntil",body.validUntil());
    }
    @Transactional public void revokeGrant(Actor actor,UUID linkId,UUID grant){var link=db.required("SELECT child_id FROM workspace_children WHERE id=:id AND workspace_id=:ws",p("id",linkId,"ws",actor.workspaceId()),"CHILD_NOT_ACCESSIBLE");policy.delegatable(actor,id(link,"child_id"));var row=db.required("SELECT * FROM child_access_grants WHERE id=:id AND workspace_id=:ws AND workspace_child_id=:wc FOR UPDATE",p("id",grant,"ws",actor.workspaceId(),"wc",linkId),"GRANT_NOT_ACCESSIBLE");db.update("UPDATE child_access_grants SET revoked_at=COALESCE(revoked_at,now()) WHERE id=:id",p("id",grant));policy.revokeStreams(id(row,"membership_id"),id(link,"child_id"));audit.record(actor.workspaceId(),actor.userId(),"grant.revoke","grant",grant);}
    @Transactional public Object share(Actor actor,Share body,String key){policy.verified(actor);policy.require(actor,body.childId(),"child:manage");var link=policy.link(actor,body.childId());if(link.get("share_grant_id")!=null)throw ApiException.forbidden("RESHARING_NOT_ALLOWED");if(!policy.delegatable(actor,body.childId()).containsAll(body.scopes()))throw ApiException.forbidden("GRANT_EXCEEDS_AUTHORITY");if(actor.workspaceId().equals(body.toWorkspaceId()))throw ApiException.invalid("SAME_WORKSPACE_SHARE");db.required("SELECT id FROM workspaces WHERE id=:id AND status='active'",p("id",body.toWorkspaceId()),"WORKSPACE_NOT_FOUND");
        return idem.execute(actor.membershipId(),key,"share.create",body,()->{UUID id=UUID.randomUUID(),wc=UUID.randomUUID();db.update("INSERT INTO data_share_grants(id,child_id,from_workspace_id,to_workspace_id,scopes,consent_ref,created_by,expires_at) VALUES(:id,:child,:from,:to,cast(:scopes as jsonb),:consent,:u,:expires)",p("id",id,"child",body.childId(),"from",actor.workspaceId(),"to",body.toWorkspaceId(),"scopes",db.json(body.scopes()),"consent",body.consentRef(),"u",actor.userId(),"expires",body.expiresAt()));db.update("INSERT INTO workspace_children(id,workspace_id,child_id,share_grant_id) VALUES(:id,:ws,:child,:share)",p("id",wc,"ws",body.toWorkspaceId(),"child",body.childId(),"share",id));audit.record(actor.workspaceId(),actor.userId(),"share.create","share",id);return p("id",id,"childId",body.childId(),"workspaceChildId",wc,"toWorkspaceId",body.toWorkspaceId(),"scopes",body.scopes(),"expiresAt",body.expiresAt());});}
    @Transactional public void revokeShare(Actor actor,UUID share){var row=db.required("SELECT * FROM data_share_grants WHERE id=:id AND from_workspace_id=:ws FOR UPDATE",p("id",share,"ws",actor.workspaceId()),"SHARE_NOT_ACCESSIBLE");policy.require(actor,id(row,"child_id"),"child:manage");db.update("UPDATE data_share_grants SET revoked_at=COALESCE(revoked_at,now()) WHERE id=:id",p("id",share));db.update("UPDATE workspace_children SET link_status='ended',ended_at=now() WHERE share_grant_id=:id",p("id",share));db.update("UPDATE child_access_grants SET revoked_at=now() WHERE workspace_child_id IN(SELECT id FROM workspace_children WHERE share_grant_id=:id)",p("id",share));db.update("UPDATE stream_access_tokens SET revoked_at=now() WHERE workspace_id=:ws AND child_id=:child",p("ws",row.get("to_workspace_id"),"child",row.get("child_id")));audit.record(actor.workspaceId(),actor.userId(),"share.revoke","share",share);}
}
